preservation_differences AS (
 SELECT 'listing' AS kind,e->>'id' AS id,k.key AS field FROM preserved_manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'preserve_listings') e LEFT JOIN public.listings l ON l.id=(e->>'id')::uuid CROSS JOIN LATERAL jsonb_each(e-'reason') k WHERE l.id IS NULL OR to_jsonb(l)->k.key IS DISTINCT FROM k.value
 UNION ALL SELECT 'location',e->>'id',k.key FROM preserved_manifest m CROSS JOIN LATERAL jsonb_array_elements(m.data->'preserve_locations') e LEFT JOIN public.locations l ON l.id=(e->>'id')::uuid CROSS JOIN LATERAL jsonb_each(e) k WHERE l.id IS NULL OR to_jsonb(l)->k.key IS DISTINCT FROM k.value
 UNION ALL SELECT 'reservation',e.expected->>'id',k.key FROM expected_preserved_reservations e LEFT JOIN public.reservations r ON r.id=(e.expected->>'id')::uuid CROSS JOIN LATERAL jsonb_each(e.expected) k WHERE r.id IS NULL OR CASE WHEN k.key IN ('created_at','collected_at') THEN (to_jsonb(r)->>k.key)::timestamptz IS DISTINCT FROM (k.value#>>'{}')::timestamptz ELSE to_jsonb(r)->k.key IS DISTINCT FROM k.value END
),
