photo_candidates AS (SELECT value AS expected FROM jsonb_array_elements($photos$[{"path": "98dff58a-df40-4894-a23b-2cb6cdd6ce87/0b85a40a-5f75-41d6-8d00-0021c75178bf.webp", "id": "8492bfd5-de6f-4351-ab5c-1d2da6ba2d99", "database_created_at": "2026-10-10T23:07:28.765460+00:00", "owner_id": "98dff58a-df40-4894-a23b-2cb6cdd6ce87"}, {"path": "98dff58a-df40-4894-a23b-2cb6cdd6ce87/1f86b066-13ed-4ca0-b115-cd90f6817c29.webp", "id": "e6c8d08b-8934-4318-a6ec-d1076e7cce96", "database_created_at": "2026-10-10T23:08:44.720853+00:00", "owner_id": "98dff58a-df40-4894-a23b-2cb6cdd6ce87"}, {"path": "98dff58a-df40-4894-a23b-2cb6cdd6ce87/433d444c-6f2c-4785-a360-c5a6544f0e37.webp", "id": "1e9d7fc1-738c-4bca-a950-b78283b40f5b", "database_created_at": "2026-10-10T22:45:15.997379+00:00", "owner_id": "98dff58a-df40-4894-a23b-2cb6cdd6ce87"}, {"path": "98dff58a-df40-4894-a23b-2cb6cdd6ce87/6aa0d4ba-0cea-4bd2-8878-170600864ea0.webp", "id": "b43d6d49-045b-4e9e-abb4-343d8996204c", "database_created_at": "2026-10-10T22:28:50.142019+00:00", "owner_id": "98dff58a-df40-4894-a23b-2cb6cdd6ce87"}, {"path": "98dff58a-df40-4894-a23b-2cb6cdd6ce87/7712bf39-6bcd-4fa2-8331-de923ca03757.webp", "id": "90e6e50b-9e89-42df-b589-cbe348228dfd", "database_created_at": "2026-10-10T23:41:35.087375+00:00", "owner_id": "98dff58a-df40-4894-a23b-2cb6cdd6ce87"}, {"path": "98dff58a-df40-4894-a23b-2cb6cdd6ce87/93066664-f2cf-4ac2-b659-03133ef2ee48.webp", "id": "fe6a2135-1665-4af6-aa5d-02d2941705e6", "database_created_at": "2026-10-10T22:29:51.163912+00:00", "owner_id": "98dff58a-df40-4894-a23b-2cb6cdd6ce87"}]$photos$::jsonb))
SELECT jsonb_build_object(
 'checked_at',now(),
 'database_role',current_user,
 'administrative_visibility',(SELECT rolsuper OR rolbypassrls FROM pg_roles WHERE rolname=current_user),
 'preservation_differences',coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM preservation_differences d),'[]'::jsonb),
 'all_photo_checks',(SELECT jsonb_agg(jsonb_build_object('path',p.expected->>'path','proposed_action',p.expected->>'proposed_action','identity_matches',EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='food-photos' AND o.name=p.expected->>'path' AND o.id=(p.expected->>'id')::uuid AND o.created_at=(p.expected->>'database_created_at')::timestamptz AND o.owner_id IS NOT DISTINCT FROM p.expected->>'owner_id'),'current_listing_references',coalesce((SELECT jsonb_agg(l.id ORDER BY l.id) FROM public.listings l WHERE l.photo_path=p.expected->>'path'),'[]'::jsonb)) ORDER BY p.expected->>'path') FROM expected_photos p),
 'remaining_approved_listings',(SELECT count(*) FROM public.listings WHERE id IN (SELECT id FROM approved_listings)),
 'remaining_approved_reservations',(SELECT count(*) FROM public.reservations WHERE id IN (SELECT id FROM approved_reservations)),
 'remaining_listing_count',(SELECT count(*) FROM public.listings),
 'remaining_reservation_count',(SELECT count(*) FROM public.reservations),
 'profile_count',(SELECT count(*) FROM public.profiles),
 'account_count',(SELECT count(*) FROM auth.users),
 'location_count',(SELECT count(*) FROM public.locations),
 'food_photo_count',(SELECT count(*) FROM storage.objects WHERE bucket_id='food-photos'),
 'impact',jsonb_build_object('posted_portions',(SELECT coalesce(sum(portions_total),0) FROM public.listings),'collected_portions',(SELECT count(*) FROM public.reservations WHERE status='collected'),'active_reserved_portions',(SELECT count(*) FROM public.reservations r JOIN public.listings l ON l.id=r.listing_id WHERE r.status='reserved' AND l.pickup_deadline>now())),
 'photo_candidates', (SELECT jsonb_agg(jsonb_build_object('path',p.expected->>'path','remaining_listing_references',(SELECT count(*) FROM public.listings l WHERE l.photo_path=p.expected->>'path'),'identity_matches',EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='food-photos' AND o.name=p.expected->>'path' AND o.id=(p.expected->>'id')::uuid AND o.created_at=(p.expected->>'database_created_at')::timestamptz AND o.owner_id IS NOT DISTINCT FROM p.expected->>'owner_id')) ORDER BY p.expected->>'path') FROM photo_candidates p)
) AS demo17_post_commit_report;
